SELECT  FROM sys_role r LEFT JOIN metal_factory f ON f.factory_id=r.factory_id AND f.del_flag='0' WHERE r.del_flag='0' AND r.factory_id=#{factoryId} AND r.role_name LIKE #{q.namePattern} ESCAPE '!'
AND r.factory_id =#{q.factoryId}
AND r.create_time >=#{q.startTime}AND r.create_time <#{q.endExclusive} ORDER BY r.role_sort,r.role_id DESC
